/**
 * Справочник городов (`geo.md`, «Состав справочника»).
 *
 * ФАЙЛ СГЕНЕРИРОВАН: `node packages/shared/scripts/build-cities.mjs`.
 * Руками не правится — правки потеряются при следующей сборке.
 *
 * Источник: GeoNames cities1000, cities1000, 135233 записей в дампе.
 * Содержит данные GeoNames (https://www.geonames.org), лицензия CC BY 4.0.
 *
 * Отбор: города РФ и СНГ с населением больше 15 000, остальной мир —
 * столицы и города-миллионники. Отсечение по населению, а не «первые N»:
 * иначе из подсказок выпадают целые регионы.
 *
 * Координаты — центр города из дампа (точность ~0.0001°). Часовой пояс
 * (IANA) обязателен: без него нельзя перевести время рождения в UTC.
 *
 * ВАЖНО: ПДн в файле нет — это публичные географические данные.
 */

export interface CityRecord {
  readonly name: string;
  /** ISO-3166 alpha-2. */
  readonly country: string;
  readonly lat: number;
  readonly lon: number;
  /** IANA-пояс, обязателен: без него нельзя перевести локальное время в UTC. */
  readonly tz: string;
  readonly population?: number;
  readonly region?: string;
  /** Столица страны: такие города попадают в справочник и при малом населении. */
  readonly capital?: boolean;
  /** Варианты написания для поиска (латиница, сокращения). */
  readonly aliases?: readonly string[];
}

